// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./PatientRegistry.sol";
import "./AccessControl.sol";

/**
 * @title HealthRecords
 * @author Ananya Aastha — N12125547 | IFB452 Blockchain Technology, QUT
 *
 * @notice Contract 3 of 3 — Health Record Storage and Retrieval
 *         Stores IPFS hashes of encrypted medical records on-chain.
 *         Raw medical data is stored off-chain on IPFS — only the CID
 *         and a keccak256 integrity hash are stored on-chain.
 *
 * @dev Cross-contract interactions:
 *   This contract calls PatientRegistry to verify stakeholder roles.
 *   This contract calls AccessControl to verify consent before returning data.
 *   This demonstrates direct smart contract interaction as required by the spec.
 *
 * @dev Architecture:
 *   PatientRegistry  ←── HealthRecords ──→  AccessControl
 *        ↑                                        ↑
 *   role checks                          consent checks
 */
contract HealthRecords {

    // ═══════════════════════════════════════════════════════════════
    //  ENUMS
    // ═══════════════════════════════════════════════════════════════

    /// @notice Defines the type of medical record being stored
    enum RecordType {
        Diagnosis,          // 0 — clinical diagnosis
        Prescription,       // 1 — medication prescription
        ImagingReport,      // 2 — X-ray, MRI, CT scan reports
        LabResult,          // 3 — blood tests, pathology results
        DischargeSummary,   // 4 — hospital discharge summary
        DispensingRecord    // 5 — pharmacist dispensing record
    }

    // ═══════════════════════════════════════════════════════════════
    //  STRUCTS
    // ═══════════════════════════════════════════════════════════════

    /// @notice Represents a single health record stored on-chain
    /// @dev Only the IPFS hash is stored — raw data lives off-chain
    struct Record {
        uint256    id;          // unique record identifier
        string     ipfsHash;    // IPFS CID pointing to encrypted file
        bytes32    fileHash;    // keccak256 of file — for integrity verification
        uint256    timestamp;   // when the record was added
        address    addedBy;     // who added the record
        RecordType recordType;  // type of medical record
        bool       isValid;     // false if record has been invalidated
    }

    // ═══════════════════════════════════════════════════════════════
    //  STORAGE
    // ═══════════════════════════════════════════════════════════════

    /// @notice Address of the contract deployer — has admin privileges
    address public admin;

    /// @notice Reference to PatientRegistry for cross-contract role verification
    PatientRegistry public registry;

    /// @notice Reference to AccessControl for cross-contract consent verification
    AccessControl public accessControl;

    /// @notice Total number of records ever added across all patients
    uint256 public totalRecords;

    /// @notice patient address => array of their health records
    mapping(address => Record[]) private patientRecords;

    // ═══════════════════════════════════════════════════════════════
    //  EVENTS
    // ═══════════════════════════════════════════════════════════════

    /// @notice Emitted when a new health record is added for a patient
    event RecordAdded(
        address    indexed patient,
        uint256    recordId,
        RecordType recordType,
        address    addedBy,
        uint256    timestamp
    );

    // ═══════════════════════════════════════════════════════════════
    //  CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Links this contract to the other two deployed contracts
     * @param _registryAddress      Address of the deployed PatientRegistry contract
     * @param _accessControlAddress Address of the deployed AccessControl contract
     */
    constructor(address _registryAddress, address _accessControlAddress) {
        admin         = msg.sender;
        registry      = PatientRegistry(_registryAddress);
        accessControl = AccessControl(_accessControlAddress);
    }

    // ═══════════════════════════════════════════════════════════════
    //  RECORD MANAGEMENT
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Add a health record for a patient
     * @dev Calls PatientRegistry to verify patient is registered.
     *      Calls AccessControl to verify consent for doctors and pharmacists.
     *      Only the IPFS hash is stored — raw data lives off-chain on IPFS.
     * @param _patient     Patient wallet address
     * @param _ipfsHash    IPFS CID of the encrypted medical file
     * @param _fileHash    keccak256 hash of the file for integrity verification
     * @param _recordType  Type of medical record being added
     */
    function addRecord(
        address    _patient,
        string     calldata _ipfsHash,
        bytes32    _fileHash,
        RecordType _recordType
    ) external {
        require(registry.isPatient(_patient), "DHRSS: patient not registered");
        require(bytes(_ipfsHash).length > 0, "DHRSS: IPFS hash cannot be empty");

        // Cross-contract calls to verify access rights
        bool isPatient    = msg.sender == _patient && registry.isPatient(msg.sender);
        bool isDoctor     = registry.isDoctor(msg.sender) && accessControl.hasValidConsent(_patient, msg.sender);
        bool isPharmacist = registry.isPharmacist(msg.sender) && accessControl.hasValidConsent(_patient, msg.sender);

        require(isPatient || isDoctor || isPharmacist, "DHRSS: no access to add record");

        totalRecords++;
        patientRecords[_patient].push(Record({
            id:         totalRecords,
            ipfsHash:   _ipfsHash,
            fileHash:   _fileHash,
            timestamp:  block.timestamp,
            addedBy:    msg.sender,
            recordType: _recordType,
            isValid:    true
        }));

        emit RecordAdded(_patient, totalRecords, _recordType, msg.sender, block.timestamp);
    }

    /**
     * @notice Retrieve all health records for a patient
     * @dev Calls PatientRegistry to verify roles.
     *      Calls AccessControl to verify consent for doctors/pharmacists/insurers.
     *      Emergency personnel can access without consent — audit log in AccessControl.
     * @param _patient Patient wallet address whose records to retrieve
     * @return Array of Record structs belonging to the patient
     */
    function getRecords(address _patient) external view returns (Record[] memory) {
        require(registry.isPatient(_patient), "DHRSS: patient not registered");

        // Cross-contract calls to verify access rights
        bool isPatient    = msg.sender == _patient && registry.isPatient(msg.sender);
        bool isDoctor     = registry.isDoctor(msg.sender) && accessControl.hasValidConsent(_patient, msg.sender);
        bool isPharmacist = registry.isPharmacist(msg.sender) && accessControl.hasValidConsent(_patient, msg.sender);
        bool isInsurer    = registry.isInsurer(msg.sender) && accessControl.hasValidConsent(_patient, msg.sender);
        bool isEmergency  = registry.isEmergencyPersonnel(msg.sender);

        require(
            isPatient || isDoctor || isPharmacist || isInsurer || isEmergency,
            "DHRSS: access denied"
        );

        return patientRecords[_patient];
    }

    /**
     * @notice Returns the total number of records for a patient
     * @param _patient Patient wallet address
     * @return Number of records stored for this patient
     */
    function getRecordCount(address _patient) external view returns (uint256) {
        require(registry.isPatient(_patient), "DHRSS: patient not registered");
        return patientRecords[_patient].length;
    }
}

contracts/AccessControl.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./PatientRegistry.sol";

/**
 * @title AccessControl
 * @author Ananya Aastha — N12125547 | IFB452 Blockchain Technology, QUT
 *
 * @notice Contract 2 of 3 — Consent and Emergency Access Management
 *         Manages time-limited consent grants between patients and providers.
 *         Handles emergency override with permanent on-chain logging.
 *         Called by HealthRecords before returning any patient data.
 *
 * @dev NOVEL features vs MedRec (Azaria et al., 2016):
 *   1. Auto-expiry consent — permissions revoke automatically at block.timestamp
 *      No patient action needed — the contract enforces expiry automatically
 *   2. Emergency override with penalty mechanism
 *      Every access is permanently logged. Unjustified access = strike.
 *      Three strikes = automatic suspension from the network.
 *
 * @dev Cross-contract interaction:
 *   This contract calls PatientRegistry to verify roles before
 *   granting or revoking consent and before allowing emergency access.
 */
contract AccessControl {

    // ═══════════════════════════════════════════════════════════════
    //  STRUCTS
    // ═══════════════════════════════════════════════════════════════

    /// @notice Stores a time-limited consent grant from patient to provider
    struct ConsentGrant {
        uint256 expiryTime;   // unix timestamp — consent invalid after this
        bool    active;       // false if manually revoked before expiry
    }

    /// @dev NOVEL — every emergency access is permanently stored on-chain
    ///      Records can never be deleted — full immutable audit trail
    struct EmergencyEvent {
        uint256 id;           // unique event identifier
        address accessor;     // emergency personnel who accessed
        address patient;      // patient whose records were accessed
        uint256 timestamp;    // when the access occurred
        uint256 expiresAt;    // 4-hour read token expiry
        string  reason;       // clinical justification — permanently stored
        bool    isReviewed;   // whether admin has reviewed this event
        bool    isJustified;  // admin's ruling on whether access was justified
        string  reviewNote;   // admin's review note
    }

    /// @dev Tracks penalty strikes against emergency personnel
    ///      Three unjustified accesses = automatic suspension
    struct Credential {
        uint256 strikeCount;  // number of unjustified accesses
        bool    isSuspended;  // true if strikeCount >= MAX_STRIKES
    }

    // ═══════════════════════════════════════════════════════════════
    //  STORAGE
    // ═══════════════════════════════════════════════════════════════

    /// @notice Address of the contract deployer — has admin privileges
    address public admin;

    /// @notice Reference to PatientRegistry for cross-contract role verification
    PatientRegistry public registry;

    /// @notice Total number of emergency events ever logged
    uint256 public totalEmergencyEvents;

    /// @notice Emergency access token lasts 4 hours — read-only window
    uint256 public constant EMERGENCY_DURATION = 4 hours;

    /// @notice Three unjustified accesses triggers automatic suspension
    uint256 public constant MAX_STRIKES = 3;

    /// @notice patient => provider => ConsentGrant
    /// @dev NOVEL — auto-expiry checked at call time, no cron job needed
    mapping(address => mapping(address => ConsentGrant)) private consents;

    /// @notice Permanent registry of all emergency events — immutable audit trail
    mapping(uint256 => EmergencyEvent) public emergencyEvents;

    /// @notice patient => list of emergency event IDs affecting them
    mapping(address => uint256[]) public patientEmergencyLog;

    /// @notice Penalty record for each emergency personnel address
    mapping(address => Credential) public credentials;

    // ═══════════════════════════════════════════════════════════════
    //  EVENTS
    // ═══════════════════════════════════════════════════════════════

    /// @notice Emitted when a patient grants time-limited consent to a provider
    event ConsentGranted(address indexed patient, address indexed provider, uint256 expiryTime);

    /// @notice Emitted when a patient manually revokes consent before expiry
    event ConsentRevoked(address indexed patient, address indexed provider, uint256 timestamp);

    /// @dev NOVEL — patient is immediately alerted on-chain when emergency access occurs
    event PatientAlerted(address indexed patient, address indexed accessor, uint256 eventId, uint256 timestamp);

    /// @notice Emitted when emergency personnel access records without consent
    event EmergencyOverride(address indexed accessor, address indexed patient, uint256 eventId, string reason, uint256 expiresAt);

    /// @notice Emitted when admin reviews an emergency access event
    event AccessReviewed(uint256 indexed eventId, bool isJustified, string note, uint256 timestamp);

    /// @dev NOVEL — emitted when emergency personnel receive a penalty strike
    event ProviderPenalised(address indexed provider, uint256 strikeCount, bool isSuspended, uint256 timestamp);

    // ═══════════════════════════════════════════════════════════════
    //  MODIFIERS
    // ═══════════════════════════════════════════════════════════════

    /// @dev Restricts function to the contract deployer only
    modifier onlyAdmin() {
        require(msg.sender == admin, "DHRSS: caller is not admin");
        _;
    }

    // ═══════════════════════════════════════════════════════════════
    //  CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════

    /// @notice Sets admin and links to the deployed PatientRegistry contract
    /// @param _registryAddress Address of the deployed PatientRegistry contract
    constructor(address _registryAddress) {
        admin    = msg.sender;
        registry = PatientRegistry(_registryAddress);
    }

    // ═══════════════════════════════════════════════════════════════
    //  CONSENT MANAGEMENT — NOVEL: auto-expiry
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice NOVEL — Grant time-limited consent to a provider
     * @dev Calls PatientRegistry to verify caller is a registered patient
     *      and that the provider is a registered doctor/pharmacist/insurer.
     *      Consent auto-expires at block.timestamp >= expiryTime — no patient action needed.
     * @param _provider    Provider wallet address to grant access to
     * @param _durationSec Duration in seconds (e.g. 86400 = 1 day, 3600 = 1 hour)
     */
    function grantConsent(address _provider, uint256 _durationSec) external {
        require(registry.isPatient(msg.sender), "DHRSS: caller is not a registered patient");
        require(_durationSec > 0, "DHRSS: duration must be > 0");
        require(
            registry.isDoctor(_provider)     ||
            registry.isPharmacist(_provider) ||
            registry.isInsurer(_provider),
            "DHRSS: address is not a registered provider"
        );
        uint256 expiry = block.timestamp + _durationSec;
        consents[msg.sender][_provider] = ConsentGrant({ expiryTime: expiry, active: true });
        emit ConsentGranted(msg.sender, _provider, expiry);
    }

    /**
     * @notice Manually revoke a provider's consent before expiry
     * @dev Calls PatientRegistry to verify caller is a registered patient
     * @param _provider Provider wallet address to revoke access from
     */
    function revokeConsent(address _provider) external {
        require(registry.isPatient(msg.sender), "DHRSS: caller is not a registered patient");
        require(consents[msg.sender][_provider].active, "DHRSS: no active consent to revoke");
        consents[msg.sender][_provider].active = false;
        emit ConsentRevoked(msg.sender, _provider, block.timestamp);
    }

    /**
     * @notice Check if a provider currently has valid non-expired consent
     * @dev Called by HealthRecords before returning patient data
     *      NOVEL — checks both active flag AND timestamp expiry
     * @param _patient  Patient wallet address
     * @param _provider Provider wallet address
     * @return true if consent is active and not yet expired
     */
    function hasValidConsent(address _patient, address _provider) external view returns (bool) {
        ConsentGrant storage grant = consents[_patient][_provider];
        return grant.active && block.timestamp < grant.expiryTime;
    }

    /// @notice Returns the expiry timestamp for a provider's consent (0 if none)
    function getConsentExpiry(address _patient, address _provider) external view returns (uint256) {
        ConsentGrant storage grant = consents[_patient][_provider];
        if (!grant.active) return 0;
        return grant.expiryTime;
    }

    // ═══════════════════════════════════════════════════════════════
    //  EMERGENCY OVERRIDE — NOVEL: on-chain alert + penalty mechanism
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice NOVEL — Emergency personnel access records without prior consent
     * @dev Calls PatientRegistry to verify caller is registered emergency personnel
     *      and that the patient is registered. Issues a 4-hour read-only token.
     *      Patient is immediately alerted on-chain via PatientAlerted event.
     *      Every access is permanently logged — records can never be deleted.
     * @param _patient  Patient wallet address whose records are being accessed
     * @param _reason   Clinical justification — stored permanently on-chain
     */
    function emergencyAccess(address _patient, string calldata _reason) external {
        require(registry.isEmergencyPersonnel(msg.sender), "DHRSS: caller is not emergency personnel");
        require(!credentials[msg.sender].isSuspended, "DHRSS: personnel is suspended");
        require(registry.isPatient(_patient), "DHRSS: patient not registered");
        require(bytes(_reason).length > 0, "DHRSS: reason required");

        totalEmergencyEvents++;
        uint256 expiresAt = block.timestamp + EMERGENCY_DURATION;

        emergencyEvents[totalEmergencyEvents] = EmergencyEvent({
            id:          totalEmergencyEvents,
            accessor:    msg.sender,
            patient:     _patient,
            timestamp:   block.timestamp,
            expiresAt:   expiresAt,
            reason:      _reason,
            isReviewed:  false,
            isJustified: false,
            reviewNote:  ""
        });

        patientEmergencyLog[_patient].push(totalEmergencyEvents);

        // NOVEL — immediately alert the patient on-chain
        emit PatientAlerted(_patient, msg.sender, totalEmergencyEvents, block.timestamp);
        emit EmergencyOverride(msg.sender, _patient, totalEmergencyEvents, _reason, expiresAt);
    }

    /**
     * @notice NOVEL — Governance review of an emergency access event
     * @dev If unjustified, _penalisePersonnel is called automatically.
     *      Three unjustified accesses = automatic suspension.
     * @param _eventId      The emergency event ID to review
     * @param _isJustified  Whether the access was clinically justified
     * @param _note         Reviewer's note explaining the decision
     */
    function reviewAccess(uint256 _eventId, bool _isJustified, string calldata _note) external onlyAdmin {
        require(_eventId > 0 && _eventId <= totalEmergencyEvents, "DHRSS: invalid event ID");
        EmergencyEvent storage e = emergencyEvents[_eventId];
        require(!e.isReviewed, "DHRSS: already reviewed");
        e.isReviewed  = true;
        e.isJustified = _isJustified;
        e.reviewNote  = _note;
        emit AccessReviewed(_eventId, _isJustified, _note, block.timestamp);
        if (!_isJustified) { _penalisePersonnel(e.accessor); }
    }

    /**
     * @notice NOVEL — Internal penalty function
     * @dev Three strikes = automatic suspension from the network
     *      Suspended personnel cannot call emergencyAccess
     * @param _person Address of the emergency personnel to penalise
     */
    function _penalisePersonnel(address _person) internal {
        Credential storage cred = credentials[_person];
        cred.strikeCount++;
        if (cred.strikeCount >= MAX_STRIKES) { cred.isSuspended = true; }
        emit ProviderPenalised(_person, cred.strikeCount, cred.isSuspended, block.timestamp);
    }

    /// @notice Returns total number of emergency events ever logged
    function getEmergencyLogCount() external view returns (uint256) {
        return totalEmergencyEvents;
    }

    /// @notice Returns penalty info for emergency personnel
    function getCredential(address _person) external view returns (uint256 strikeCount, bool isSuspended) {
        return (credentials[_person].strikeCount, credentials[_person].isSuspended);
    }
}

contracts/PatientRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title PatientRegistry
 * @author Ananya Aastha — N12125547 | IFB452 Blockchain Technology, QUT
 *
 * @notice Contract 1 of 3 — Stakeholder Registration
 *         Manages all role assignments for the DHRSS system.
 *         This is the source of truth for identity verification.
 *         AccessControl and HealthRecords call this contract to verify roles
 *         before performing any sensitive operations.
 *
 * @dev Stakeholders:
 *   1. Patient          — self-registers using their wallet
 *   2. Doctor           — registered by admin after credential verification
 *   3. Pharmacist       — registered by admin
 *   4. Insurer          — registered by admin, read-only with patient consent
 *   5. Emergency        — registered by admin, bypass consent in emergencies
 *   6. Regulator        — registered by admin, anonymised audit access only
 */
contract PatientRegistry {

    // ═══════════════════════════════════════════════════════════════
    //  ENUMS
    // ═══════════════════════════════════════════════════════════════

    /// @notice Defines all stakeholder roles in the DHRSS system
    enum Role {
        None,           // 0 — unregistered address
        Patient,        // 1 — self-registered patient
        Doctor,         // 2 — admin-verified medical doctor
        Pharmacist,     // 3 — admin-verified pharmacist
        Insurer,        // 4 — admin-verified insurance company
        Emergency,      // 5 — admin-verified emergency personnel
        Regulator       // 6 — government regulator / admin
    }

    // ═══════════════════════════════════════════════════════════════
    //  STORAGE
    // ═══════════════════════════════════════════════════════════════

    /// @notice Address of the contract deployer — has admin privileges
    address public admin;

    /// @notice Role registries — one mapping per stakeholder type
    mapping(address => bool) public registeredPatients;
    mapping(address => bool) public doctors;
    mapping(address => bool) public pharmacists;
    mapping(address => bool) public insurers;
    mapping(address => bool) public emergencyPersonnel;
    mapping(address => bool) public regulators;

    // ═══════════════════════════════════════════════════════════════
    //  EVENTS
    // ═══════════════════════════════════════════════════════════════

    /// @notice Emitted when a patient self-registers
    event PatientRegistered(address indexed patient, uint256 timestamp);

    /// @notice Emitted when admin registers any provider role
    event ProviderRegistered(address indexed provider, Role role, uint256 timestamp);

    // ═══════════════════════════════════════════════════════════════
    //  MODIFIERS
    // ═══════════════════════════════════════════════════════════════

    /// @dev Restricts function to the contract deployer only
    modifier onlyAdmin() {
        require(msg.sender == admin, "DHRSS: caller is not admin");
        _;
    }

    // ═══════════════════════════════════════════════════════════════
    //  CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════

    /// @notice Sets the deployer as admin on deployment
    constructor() {
        admin = msg.sender;
    }

    // ═══════════════════════════════════════════════════════════════
    //  REGISTRATION — Stakeholders 1 to 6
    // ═══════════════════════════════════════════════════════════════

    /// @notice Stakeholder 1 — Patients self-register using their wallet
    /// @dev No admin approval needed — patients own their registration
    function registerPatient() external {
        require(!registeredPatients[msg.sender], "DHRSS: already registered");
        registeredPatients[msg.sender] = true;
        emit PatientRegistered(msg.sender, block.timestamp);
    }

    /// @notice Stakeholder 2 — Admin registers a verified doctor / GP
    /// @param _doctor Wallet address of the doctor to register
    function registerDoctor(address _doctor) external onlyAdmin {
        require(_doctor != address(0), "DHRSS: zero address");
        require(!doctors[_doctor], "DHRSS: already registered as doctor");
        doctors[_doctor] = true;
        emit ProviderRegistered(_doctor, Role.Doctor, block.timestamp);
    }

    /// @notice Stakeholder 3 — Admin registers a pharmacist
    /// @param _pharmacist Wallet address of the pharmacist to register
    function registerPharmacist(address _pharmacist) external onlyAdmin {
        require(_pharmacist != address(0), "DHRSS: zero address");
        require(!pharmacists[_pharmacist], "DHRSS: already registered as pharmacist");
        pharmacists[_pharmacist] = true;
        emit ProviderRegistered(_pharmacist, Role.Pharmacist, block.timestamp);
    }

    /// @notice Stakeholder 4 — Admin registers an insurance company
    /// @param _insurer Wallet address of the insurer to register
    function registerInsurer(address _insurer) external onlyAdmin {
        require(_insurer != address(0), "DHRSS: zero address");
        require(!insurers[_insurer], "DHRSS: already registered as insurer");
        insurers[_insurer] = true;
        emit ProviderRegistered(_insurer, Role.Insurer, block.timestamp);
    }

    /// @notice Stakeholder 5 — Admin registers emergency personnel
    /// @dev Emergency personnel can bypass consent in genuine emergencies
    /// @param _person Wallet address of the emergency personnel to register
    function registerEmergencyPersonnel(address _person) external onlyAdmin {
        require(_person != address(0), "DHRSS: zero address");
        require(!emergencyPersonnel[_person], "DHRSS: already registered");
        emergencyPersonnel[_person] = true;
        emit ProviderRegistered(_person, Role.Emergency, block.timestamp);
    }

    /// @notice Stakeholder 6 — Admin registers a government regulator
    /// @param _regulator Wallet address of the regulator to register
    function registerRegulator(address _regulator) external onlyAdmin {
        require(_regulator != address(0), "DHRSS: zero address");
        require(!regulators[_regulator], "DHRSS: already registered as regulator");
        regulators[_regulator] = true;
        emit ProviderRegistered(_regulator, Role.Regulator, block.timestamp);
    }

    // ═══════════════════════════════════════════════════════════════
    //  ROLE CHECKS — called externally by AccessControl and HealthRecords
    // ═══════════════════════════════════════════════════════════════

    /// @notice Check if an address is a registered patient
    function isPatient(address _addr) external view returns (bool) {
        return registeredPatients[_addr];
    }

    /// @notice Check if an address is a registered doctor
    function isDoctor(address _addr) external view returns (bool) {
        return doctors[_addr];
    }

    /// @notice Check if an address is a registered pharmacist
    function isPharmacist(address _addr) external view returns (bool) {
        return pharmacists[_addr];
    }

    /// @notice Check if an address is a registered insurer
    function isInsurer(address _addr) external view returns (bool) {
        return insurers[_addr];
    }

    /// @notice Check if an address is registered emergency personnel
    function isEmergencyPersonnel(address _addr) external view returns (bool) {
        return emergencyPersonnel[_addr];
    }

    /// @notice Check if an address is a registered regulator
    function isRegulator(address _addr) external view returns (bool) {
        return regulators[_addr];
    }

    /// @notice Returns the role enum for any address
    function getRole(address _addr) external view returns (Role) {
        if (_addr == admin)                return Role.Regulator;
        if (registeredPatients[_addr])     return Role.Patient;
        if (doctors[_addr])                return Role.Doctor;
        if (pharmacists[_addr])            return Role.Pharmacist;
        if (insurers[_addr])               return Role.Insurer;
        if (emergencyPersonnel[_addr])     return Role.Emergency;
        if (regulators[_addr])             return Role.Regulator;
        return Role.None;
    }
}

